<?php
require_once __DIR__.'/../admin.php';$id=(int)getIdFromUserid($_SESSION[USER_AUTH]);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{if(!hash_equals(sc_csrf(),(string)($_POST['csrf']??'')))throw new RuntimeException('Your session expired. Reload this page.');$theme=$_POST['theme']??'classic';$accent=$_POST['accent']??'#696cff';admin_appearance_validate($theme,$accent);$previous=admin_appearance_get($id);$image=isset($_POST['remove_background'])?'':$previous['background_image'];if(!empty($_FILES['background']['name'])){$f=$_FILES['background'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>1048576)throw new RuntimeException('Choose an image up to 1 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp','image/gif'],true))throw new RuntimeException('Use a JPEG, PNG, WebP or GIF image.');$result=upload_file('background');if($result['status']!=='success')throw new RuntimeException($result['message']);$image=$result['file_name'];}sc_query('INSERT INTO admin_appearance (user_id,theme,accent,background_image) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE theme=VALUES(theme),accent=VALUES(accent),background_image=VALUES(background_image)','isss',[$id,$theme,$accent,$image]);header('Location: ./?saved=1',true,303);exit;}catch(Throwable $e){$error=$e instanceof mysqli_sql_exception?'Could not save your appearance. Please try again.':$e->getMessage();}
}
$p=admin_appearance_get($id);
