<!doctype html><html lang="en"><head><?= loadAdminMetaData() ?><?= loadAdminTitleAndFavicon('My appearance') ?><?= loadAdminStyleSheets() ?></head><body><main class="sc-appearance-page"><a href="<?= sc_url('admin/dashboard/') ?>">&larr; Dashboard</a><h1>Make this space yours.</h1><p>Your appearance settings apply only to your account, across admin pages.</p><?php if(isset($_GET['saved'])): ?><div class="alert alert-success" role="status">Your appearance is saved.</div><?php endif; ?><?php if($error): ?><div class="alert alert-danger" role="alert"><?= sc_e($error) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data"><?= sc_token() ?><div class="sc-theme-grid"><?php foreach(['classic'=>['Classic','Clean, familiar workspace.','#696cff'],'xp'=>['Windows XP','Luna blue, green accents and a sky-like desktop.','#245edb'],'midnight'=>['Midnight black','Dark surfaces with crisp accents.','#60a5fa'],'forest'=>['Forest','Calm greens and warm neutral surfaces.','#26765a'],'blood'=>['Red Blood','Deep burgundy with crimson accents.','#bf2545'],'chess'=>['Chess Board','Black and ivory with a patterned desktop.','#333333'],'cartoon'=>['Cartoon','Playful outlines, bold colours and rounded cards.','#7651ce'],'lavender'=>['Lavender','Soft purple, with a lighter feel.','#8559c5']] as $key=>$preset): ?><label class="sc-theme-card"><input type="radio" name="theme" value="<?= $key ?>" <?= $p['theme']===$key?'checked':'' ?>><span class="sc-theme-preview sc-preview-<?= $key ?>"><i></i><b></b><em></em></span><strong><?= $preset[0] ?></strong><small><?= $preset[1] ?></small></label><?php endforeach; ?></div><div class="card p-4 my-4"><label for="accent">Accent colour</label><input id="accent" name="accent" type="color" value="<?= sc_e($p['accent']) ?>"><label for="background" class="mt-3">Background image (up to 1 MB)</label><input class="form-control" type="file" id="background" name="background" accept="image/jpeg,image/png,image/webp,image/gif"><label class="mt-3"><input type="checkbox" name="remove_background"> Remove my custom background</label></div><button class="btn btn-primary" type="submit">Save my appearance</button><a class="btn btn-outline-secondary" href="./">Discard changes</a></form><script>document.querySelectorAll('input[name="theme"]').forEach(r=>r.addEventListener('change',()=>{document.documentElement.dataset.adminTheme=r.value;const colors={classic:'#696cff',xp:'#245edb',midnight:'#60a5fa',forest:'#26765a',lavender:'#8559c5',blood:'#bf2545',chess:'#333333',cartoon:'#7651ce'};document.querySelector('#accent').value=colors[r.value];document.documentElement.style.setProperty('--admin-accent',colors[r.value]);}));document.querySelector('#accent').addEventListener('input',e=>document.documentElement.style.setProperty('--admin-accent',e.target.value));</script></main></body></html>
